mapper.select:
select ifnull(sum(o.quantity), 0)     as week_ticket_count,
       ifnull(sum(o.total_amount), 0) as week_revenue
from exhibition_order o
join exhibition e on e.id = o.exhibition_id
join gallery g on g.id = o.gallery_id

    o.status in (2, 5)
    and o.pay_time >= #{start} and o.pay_time < #{end}

        and g.city = #{city}


        and e.type = #{type}

sql.where:
o.status in (2, 5)
and o.pay_time >= #{dto.startTime} and o.pay_time < #{dto.endTime}

    and g.city = #{dto.city}


    and e.type = #{dto.type}

o.status in (2, 5)
and o.pay_time >= #{start} and o.pay_time < #{end}

    and g.city = #{city}


    and e.type = #{type}

mapper.select:
select e.id as exhibition_id, e.title as exhibition_name, ifnull(sum(o.quantity), 0) as ticket_count from exhibition_order o join exhibition e on e.id = o.exhibition_id join gallery g on g.id = o.gallery_id
group by e.id, e.title
order by ticket_count desc, e.id asc limit #{dto.offset}, #{dto.limit}

sql.where:
o.status in (2, 5)
and o.pay_time is not null
and o.pay_time >= #{dto.startTime} and o.pay_time < #{dto.endTime}

    and g.city = #{dto.city}


    and e.type = #{dto.type}


    and e.title like concat('%', #{dto.keyword}, '%')

mapper.select:
select date(o.use_time) as stat_date, e.id as exhibition_id, ifnull(sum(o.quantity), 0) as verified_count from exhibition_order o join exhibition e on e.id = o.exhibition_id join gallery g on g.id = o.gallery_id
o.use_time is not null and o.use_time >= #{dto.startTime} and o.use_time < #{dto.endTime}
and g.city = #{dto.city}
and e.type = #{dto.type}
and e.title like concat('%', #{dto.keyword}, '%')
group by date(o.use_time), e.id

select

    (select ifnull(sum(o.quantity), 0)
     from exhibition_order o
     join exhibition e on e.id = o.exhibition_id
     join gallery g on g.id = o.gallery_id

    ) as total_sold_count,


    (select ifnull(sum(o.quantity), 0)
     from exhibition_order o
     join exhibition e on e.id = o.exhibition_id
     join gallery g on g.id = o.gallery_id

         o.use_time is not null
         and o.use_time >= #{dto.startTime} and o.use_time < #{dto.endTime}

             and g.city = #{dto.city}


             and e.type = #{dto.type}


             and e.title like concat('%', #{dto.keyword}, '%')


    ) as total_verified_count,


    (select ifnull(sum(o.total_amount), 0)
     from exhibition_order o
     where o.status in (2, 5)
       and o.pay_time >= #{todayStart} and o.pay_time < #{todayEnd}
    ) as today_revenue
